import { GoogleGenAI, Type } from "@google/genai";
import { SuggestedTask } from '../types';

export const generateStudyPlan = async (goal: string, apiKey: string): Promise<SuggestedTask[] | null> => {
  if (!apiKey) {
    console.error("API key is missing.");
    return null;
  }

  const ai = new GoogleGenAI({ apiKey: apiKey });

  try {
    const prompt = `あなたは優秀な学習プランナーです。生徒の目標「${goal}」を達成するための、構造化された学習タスクのJSON配列を作成してください。各タスクには、タイトル(title)、内容(description)、推定学習時間(estimatedHours)（時間単位の数値）を含めてください。現実的で実行可能な計画を提案してください。`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: {
                type: Type.STRING,
                description: 'タスクのタイトル',
              },
              description: {
                type: Type.STRING,
                description: 'タスクの具体的な内容',
              },
              estimatedHours: {
                type: Type.NUMBER,
                description: '推定学習時間（時間単位）',
              },
            },
            required: ["title", "description", "estimatedHours"],
          },
        },
      },
    });

    const jsonString = response.text.trim();
    const tasks = JSON.parse(jsonString) as SuggestedTask[];
    return tasks;

  } catch (error) {
    console.error("Error generating study plan with Gemini:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Subject, Task, TaskType, UserProgress, Badge } from './types';
import useLocalStorage from './hooks/useLocalStorage';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import Header from './components/Header';
import SettingsMenu from './components/SettingsMenu';
import Sidebar from './components/Sidebar';
import ProgressView from './components/ProgressView';
import SubjectManager from './components/SubjectManager';

const SIDEBAR_COLORS = [
  '#F87171', '#FB923C', '#FBBF24', '#A3E635', '#4ADE80', '#34D399', '#2DD4BF', '#60A5FA', '#818CF8', '#A78BFA', '#F472B6'
];

const INITIAL_BADGES: Badge[] = [
  { id: 'first_step', name: 'はじめの一歩', description: '最初のタスクを完了', icon: 'check', achieved: false },
  { id: 'study_10h', name: '勉強家', description: '合計10時間勉強', icon: 'book', achieved: false },
  { id: 'study_50h', name: '努力家', description: '合計50時間勉強', icon: 'book', achieved: false },
  { id: 'perfect_week', name: 'パーフェクトウィーク', description: '1週間の全タスクを完了', icon: 'calendar', achieved: false },
  { id: 'deadline_master', name: '締切マスター', description: '5つの提出タスクを完了', icon: 'flag', achieved: false },
];

const XP_PER_HOUR = 20;
const XP_PER_DEADLINE = 50;
const LEVEL_UP_BASE_XP = 100;

type View = 'calendar' | 'progress' | 'subjects';

const App: React.FC = () => {
  const [subjects, setSubjects] = useLocalStorage<Subject[]>('subjects', []);
  const [tasks, setTasks] = useLocalStorage<Task[]>('tasks', []);
  const [userProgress, setUserProgress] = useLocalStorage<UserProgress>('userProgress', {
    level: 1,
    xp: 0,
    badges: INITIAL_BADGES,
  });
  const [apiKey, setApiKey] = useLocalStorage<string>('gemini_api_key', '');

  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [taskToEdit, setTaskToEdit] = useState<Task | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [notificationPermission, setNotificationPermission] = useState(Notification.permission);
  const [activeView, setActiveView] = useState<View>('calendar');

  const notificationTimeouts = useRef<number[]>([]);

  const handleRequestNotificationPermission = useCallback(() => {
    Notification.requestPermission().then(permission => {
        setNotificationPermission(permission);
    });
  }, []);

  useEffect(() => {
    notificationTimeouts.current.forEach(clearTimeout);
    notificationTimeouts.current = [];

    if (notificationPermission === 'granted') {
      const now = new Date();
      tasks.forEach(task => {
        if (task.notificationEnabled && task.startTime && !task.isCompleted) {
          const [hours, minutes] = task.startTime.split(':').map(Number);
          const notificationDate = new Date(task.date);
          notificationDate.setHours(hours, minutes, 0, 0);

          if (notificationDate > now) {
            const timeout = window.setTimeout(() => {
              new Notification('学習の時間です！', {
                body: `${task.title}`,
                icon: '/favicon.ico' 
              });
            }, notificationDate.getTime() - now.getTime());
            notificationTimeouts.current.push(timeout);
          }
        }
      });
    }

    return () => {
      notificationTimeouts.current.forEach(clearTimeout);
    };
  }, [tasks, notificationPermission]);

  const xpForNextLevel = LEVEL_UP_BASE_XP * userProgress.level;

  const checkAchievements = useCallback(() => {
    let newProgress = { ...userProgress };
    let newBadges = [...newProgress.badges];
    let changed = false;

    let firstStepBadge = newBadges.find(b => b.id === 'first_step');
    if (firstStepBadge && !firstStepBadge.achieved && tasks.some(t => t.isCompleted)) {
      firstStepBadge.achieved = true;
      changed = true;
    }

    const totalStudyHours = tasks
      .filter(t => t.type === TaskType.STUDY && t.isCompleted && t.duration)
      .reduce((sum, task) => sum + (task.duration || 0), 0);

    let study10hBadge = newBadges.find(b => b.id === 'study_10h');
    if (study10hBadge && !study10hBadge.achieved && totalStudyHours >= 10) {
      study10hBadge.achieved = true;
      changed = true;
    }

    let study50hBadge = newBadges.find(b => b.id === 'study_50h');
    if (study50hBadge && !study50hBadge.achieved && totalStudyHours >= 50) {
      study50hBadge.achieved = true;
      changed = true;
    }

    const completedDeadlines = tasks.filter(t => t.type === TaskType.DEADLINE && t.isCompleted).length;
    let deadlineMasterBadge = newBadges.find(b => b.id === 'deadline_master');
    if (deadlineMasterBadge && !deadlineMasterBadge.achieved && completedDeadlines >= 5) {
      deadlineMasterBadge.achieved = true;
      changed = true;
    }

    let currentXp = newProgress.xp;
    let currentLevel = newProgress.level;
    let requiredXp = LEVEL_UP_BASE_XP * currentLevel;
    while (currentXp >= requiredXp) {
        currentXp -= requiredXp;
        currentLevel += 1;
        requiredXp = LEVEL_UP_BASE_XP * currentLevel;
        changed = true;
    }
    newProgress.level = currentLevel;
    newProgress.xp = currentXp;

    if (changed) {
      newProgress.badges = newBadges;
      setUserProgress(newProgress);
    }
  }, [tasks, userProgress, setUserProgress]);

  useEffect(() => {
    checkAchievements();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tasks]);

  const handleDateClick = (date: Date) => {
    setSelectedDate(date);
    setTaskToEdit(null);
    setIsModalOpen(true);
  };

  const handleTaskClick = (task: Task) => {
    setSelectedDate(new Date(task.date));
    setTaskToEdit(task);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskData: Omit<Task, 'id' | 'isCompleted'>) => {
    if(taskData.notificationEnabled && notificationPermission !== 'granted') {
        handleRequestNotificationPermission();
    }

    if (taskToEdit) {
      setTasks(tasks.map(t => t.id === taskToEdit.id ? { ...taskToEdit, ...taskData } : t));
    } else {
      const newTask: Task = {
        ...taskData,
        id: crypto.randomUUID(),
        isCompleted: false,
      };
      setTasks([...tasks, newTask]);
    }
    setTaskToEdit(null);
  };

  const handleToggleTaskCompletion = (taskId: string) => {
    let xpGained = 0;
    const updatedTasks = tasks.map(t => {
      if (t.id === taskId) {
        const wasCompleted = t.isCompleted;
        if (!wasCompleted) {
            if (t.type === TaskType.STUDY && t.duration) xpGained = t.duration * XP_PER_HOUR;
            else if (t.type === TaskType.DEADLINE) xpGained = XP_PER_DEADLINE;
        } else {
             if (t.type === TaskType.STUDY && t.duration) xpGained = -(t.duration * XP_PER_HOUR);
             else if (t.type === TaskType.DEADLINE) xpGained = -XP_PER_DEADLINE;
        }
        return { ...t, isCompleted: !t.isCompleted };
      }
      return t;
    });

    setUserProgress(prev => ({...prev, xp: Math.max(0, prev.xp + xpGained)}));
    setTasks(updatedTasks);
  };

  const handleAddSuggestedTasks = (newTasks: Omit<Task, 'id' | 'isCompleted'>[]) => {
      const tasksToAdd: Task[] = newTasks.map(t => ({
          ...t,
          id: crypto.randomUUID(),
          isCompleted: false
      }));
      setTasks(prevTasks => [...prevTasks, ...tasksToAdd]);
      setActiveView('calendar'); // Switch to calendar view to see the new tasks
  };

  const renderContent = () => {
    switch(activeView) {
      case 'calendar':
        return (
          <Calendar
            currentDate={currentDate} tasks={tasks} subjects={subjects}
            onDateClick={handleDateClick} onTaskClick={handleTaskClick}
            onPrevMonth={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))}
            onNextMonth={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))}
            onToggleTaskCompletion={handleToggleTaskCompletion}
          />
        );
      case 'progress':
        return <ProgressView userProgress={userProgress} xpForNextLevel={xpForNextLevel} />;
      case 'subjects':
        return (
          <SubjectManager 
            subjects={subjects}
            setSubjects={setSubjects}
            tasks={tasks}
            setTasks={setTasks}
            SIDEBAR_COLORS={SIDEBAR_COLORS}
            onAddSuggestedTasks={handleAddSuggestedTasks}
            apiKey={apiKey}
          />
        );
      default:
        return null;
    }
  }

  return (
    <div className="flex flex-col h-screen bg-slate-100 relative overflow-hidden">
      <style>{`
        @keyframes modal-enter { from { opacity: 0; transform: translateY(20px) scale(0.98); } to { opacity: 1; transform: translateY(0) scale(1); } }
        .animate-modal-enter { animation: modal-enter 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards; }
        @keyframes settings-enter { from { opacity: 0; transform: translateY(-10px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
        .animate-settings-enter { animation: settings-enter 0.2s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out forwards; }
        @keyframes overlay-enter { from { opacity: 0; } to { opacity: 1; } }
        .animate-overlay-enter { animation: overlay-enter 0.3s ease-out forwards; }
      `}</style>

      <Header 
        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <Sidebar
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        activeView={activeView}
        onNavigate={(view: View) => {
          setActiveView(view);
          setIsSidebarOpen(false); // Close sidebar on navigation
        }}
      />

      {isSidebarOpen && (
          <div 
              className="fixed inset-0 bg-black bg-opacity-50 z-40 animate-overlay-enter md:hidden"
              onClick={() => setIsSidebarOpen(false)}
          ></div>
      )}

      <main className="flex-1 p-4 lg:p-6 overflow-hidden">
        <div className="h-full w-full overflow-y-auto">
          {renderContent()}
        </div>
      </main>

      <TaskModal
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveTask}
        subjects={subjects} selectedDate={selectedDate} taskToEdit={taskToEdit}
      />

      <SettingsMenu
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        notificationPermission={notificationPermission}
        onRequestNotificationPermission={handleRequestNotificationPermission}
        apiKey={apiKey}
        setApiKey={setApiKey}
      />
    </div>
  );
};

export default App;

import React from 'react';
import Icon from './Icon';

interface SettingsMenuProps {
  isOpen: boolean;
  onClose: () => void;
  notificationPermission: string;
  onRequestNotificationPermission: () => void;
  apiKey: string;
  setApiKey: (key: string) => void;
}

const SettingsMenu: React.FC<SettingsMenuProps> = ({
  isOpen,
  onClose,
  notificationPermission,
  onRequestNotificationPermission,
  apiKey,
  setApiKey
}) => {
  if (!isOpen) return null;

  return (
    <div className="absolute top-16 right-4 z-50 w-72 bg-white rounded-xl shadow-2xl border border-slate-200 p-5 animate-settings-enter origin-top-right flex flex-col gap-4">
      <div className="flex justify-between items-center">
        <h3 className="font-bold text-slate-800 text-lg">設定</h3>
        <button onClick={onClose} className="text-slate-500 hover:text-slate-800 transition-colors">
          <Icon name="x" className="w-5 h-5" />
        </button>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-slate-600 mb-2">通知設定</label>
          {notificationPermission === 'granted' ? (
            <p className="text-sm text-green-700 bg-green-50 p-2.5 rounded-lg border border-green-100 flex items-center gap-2">
              <Icon name="check" className="w-4 h-4" />
              通知は有効です
            </p>
          ) : (
            <button
              onClick={onRequestNotificationPermission}
              disabled={notificationPermission === 'denied'}
              className="w-full px-4 py-2.5 bg-indigo-500 text-white text-sm font-semibold rounded-lg shadow-sm hover:bg-indigo-600 transition disabled:bg-slate-300 disabled:cursor-not-allowed"
            >
              {notificationPermission === 'denied' ? '通知がブロックされています' : '通知を許可する'}
            </button>
          )}
        </div>

        <div className="pt-4 border-t border-slate-100">
           <label className="block text-sm font-medium text-slate-600 mb-2">Gemini APIキー</label>
           <p className="text-xs text-slate-400 mb-2">AI機能を使用するにはAPIキーが必要です。</p>
           <input 
             type="password"
             value={apiKey}
             onChange={(e) => setApiKey(e.target.value)}
             placeholder="APIキーを入力..."
             className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
           />
           <div className="mt-2 text-xs text-right">
              <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noopener noreferrer" className="text-indigo-600 hover:underline">
                キーを取得する &rarr;
              </a>
           </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsMenu;

import React, { useState } from 'react';
import { Subject, Task } from '../types';
import Icon from './Icon';
import GeminiSuggester from './GeminiSuggester';

interface SubjectManagerProps {
    subjects: Subject[];
    setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
    tasks: Task[];
    setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
    SIDEBAR_COLORS: string[];
    onAddSuggestedTasks: (tasks: Omit<Task, 'id' | 'isCompleted'>[]) => void;
    apiKey: string;
}

const SubjectManager: React.FC<SubjectManagerProps> = ({ subjects, setSubjects, tasks, setTasks, SIDEBAR_COLORS, onAddSuggestedTasks, apiKey }) => {
    const [newSubjectName, setNewSubjectName] = useState('');
    const [newSubjectGoal, setNewSubjectGoal] = useState('');
    const [newSubjectColor, setNewSubjectColor] = useState(SIDEBAR_COLORS[0]);
    const [editingSubject, setEditingSubject] = useState<Subject | null>(null);

    const handleAddSubject = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newSubjectName.trim()) return;

        const newSubject: Subject = {
            id: crypto.randomUUID(),
            name: newSubjectName,
            goal: newSubjectGoal,
            color: newSubjectColor,
        };
        setSubjects([...subjects, newSubject]);
        setNewSubjectName('');
        setNewSubjectGoal('');
        setNewSubjectColor(SIDEBAR_COLORS[0]);
    };

    const handleUpdateSubject = (e: React.FormEvent) => {
        e.preventDefault();
        if (!editingSubject) return;
        setSubjects(subjects.map(s => s.id === editingSubject.id ? editingSubject : s));
        setEditingSubject(null);
    };

    const handleDeleteSubject = (subjectId: string) => {
        if (window.confirm('この科目を削除しますか？関連する全てのタスクも削除されます。')) {
            setSubjects(subjects.filter(s => s.id !== subjectId));
            setTasks(tasks.filter(t => t.subjectId !== subjectId));
        }
    };

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="bg-white p-6 rounded-2xl shadow-lg border border-slate-200">
                <h2 className="text-2xl font-bold text-slate-800 mb-4">科目管理</h2>

                {/* Edit Form */}
                {editingSubject ? (
                    <form onSubmit={handleUpdateSubject} className="space-y-4 p-4 bg-indigo-50 rounded-xl mb-6 shadow-inner border border-indigo-100">
                        <h3 className="font-semibold text-lg text-indigo-800">科目を編集</h3>
                        <div>
                            <label htmlFor="edit-name" className="block text-sm font-medium text-slate-600 mb-1">科目名</label>
                            <input
                                id="edit-name" type="text" value={editingSubject.name}
                                onChange={(e) => setEditingSubject({ ...editingSubject, name: e.target.value })}
                                className="w-full px-4 py-2 bg-white text-slate-800 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition" 
                                required
                            />
                        </div>
                         <div>
                            <label htmlFor="edit-goal" className="block text-sm font-medium text-slate-600 mb-1">目標</label>
                            <input
                                id="edit-goal" type="text" value={editingSubject.goal}
                                onChange={(e) => setEditingSubject({ ...editingSubject, goal: e.target.value })}
                                placeholder="例: テストで90点以上取る"
                                className="w-full px-4 py-2 bg-white text-slate-800 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-600 mb-1">カラー</label>
                            <div className="flex flex-wrap gap-2">
                                {SIDEBAR_COLORS.map(color => (
                                    <button type="button" key={color} onClick={() => setEditingSubject({ ...editingSubject, color: color })}
                                        className={`w-8 h-8 rounded-full transition-transform transform hover:scale-110 shadow-sm border border-black/5 ${editingSubject.color === color ? 'ring-2 ring-offset-2 ring-indigo-500 scale-110' : ''}`}
                                        style={{ backgroundColor: color }}
                                    ></button>
                                ))}
                            </div>
                        </div>
                        <div className="flex gap-2 justify-end pt-2">
                            <button type="button" onClick={() => setEditingSubject(null)} className="px-4 py-2 bg-white text-slate-600 border border-slate-300 font-semibold rounded-lg hover:bg-slate-50 transition">キャンセル</button>
                            <button type="submit" className="px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg shadow-md hover:bg-indigo-700 transition">更新</button>
                        </div>
                    </form>
                ) : (
                /* Add Form */
                    <form onSubmit={handleAddSubject} className="space-y-4 p-5 bg-slate-50/80 rounded-xl mb-6 border border-slate-100">
                         <h3 className="font-semibold text-lg text-slate-700">新しい科目を追加</h3>
                        <div>
                            <label htmlFor="new-name" className="block text-sm font-medium text-slate-600 mb-1">科目名</label>
                            <input
                                id="new-name" type="text" value={newSubjectName}
                                onChange={(e) => setNewSubjectName(e.target.value)}
                                placeholder="例: 数学I"
                                className="w-full px-4 py-2 bg-white text-slate-800 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition shadow-sm" 
                                required
                            />
                        </div>
                        <div>
                            <label htmlFor="new-goal" className="block text-sm font-medium text-slate-600 mb-1">目標</label>
                            <input
                                id="new-goal" type="text" value={newSubjectGoal}
                                onChange={(e) => setNewSubjectGoal(e.target.value)}
                                placeholder="例: 期末テストで90点以上"
                                className="w-full px-4 py-2 bg-white text-slate-800 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition shadow-sm"
                            />
                        </div>
                        <div>
                             <label className="block text-sm font-medium text-slate-600 mb-1">カラー</label>
                            <div className="flex flex-wrap gap-2">
                                {SIDEBAR_COLORS.map(color => (
                                    <button type="button" key={color} onClick={() => setNewSubjectColor(color)}
                                        className={`w-8 h-8 rounded-full transition-transform transform hover:scale-110 shadow-sm border border-black/5 ${newSubjectColor === color ? 'ring-2 ring-offset-2 ring-indigo-500 scale-110' : ''}`}
                                        style={{ backgroundColor: color }}
                                    ></button>
                                ))}
                            </div>
                        </div>
                        <div className="flex justify-end pt-2">
                            <button type="submit" className="px-6 py-2.5 bg-indigo-600 text-white font-semibold rounded-lg shadow-md hover:bg-indigo-700 transition flex items-center gap-2 transform active:scale-95">
                                <Icon name="plus" className="w-5 h-5" />
                                <span>追加</span>
                            </button>
                        </div>
                    </form>
                )}

                {/* Subject List */}
                <div className="space-y-3">
                    {subjects.map(subject => (
                        <div key={subject.id} className="flex items-center justify-between p-4 bg-white border border-slate-200 rounded-xl hover:shadow-md transition-shadow">
                            <div className="flex items-center gap-4">
                                <span className="w-5 h-5 rounded-full shadow-sm ring-1 ring-black/5" style={{ backgroundColor: subject.color }}></span>
                                <div >
                                    <p className="font-bold text-slate-800 text-lg">{subject.name}</p>
                                    {subject.goal && <p className="text-sm text-slate-500 mt-0.5">{subject.goal}</p>}
                                </div>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => setEditingSubject(subject)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition"><Icon name="settings" className="w-5 h-5" /></button>
                                <button onClick={() => handleDeleteSubject(subject.id)} className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition"><Icon name="trash" className="w-5 h-5" /></button>
                            </div>
                        </div>
                    ))}
                     {subjects.length === 0 && !editingSubject && (
                        <div className="text-center py-8 bg-slate-50 rounded-xl border border-dashed border-slate-300">
                             <p className="text-slate-500">まだ科目がありません。<br/>新しい科目を追加して学習を始めましょう！</p>
                        </div>
                    )}
                </div>
            </div>

            <GeminiSuggester subjects={subjects} onAddSuggestedTasks={onAddSuggestedTasks} apiKey={apiKey} />
        </div>
    );
};

export default SubjectManager;

import React, { useState } from 'react';
import { generateStudyPlan } from '../services/geminiService';
import { SuggestedTask, Task, TaskType, Subject } from '../types';
import Icon from './Icon';

interface GeminiSuggesterProps {
    subjects: Subject[];
    onAddSuggestedTasks: (tasks: Omit<Task, 'id' | 'isCompleted'>[]) => void;
    apiKey: string;
}

const GeminiSuggester: React.FC<GeminiSuggesterProps> = ({ subjects, onAddSuggestedTasks, apiKey }) => {
    const [goal, setGoal] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [suggestedTasks, setSuggestedTasks] = useState<SuggestedTask[]>([]);
    const [error, setError] = useState<string | null>(null);

    const handleGeneratePlan = async () => {
        if (!apiKey) {
            setError('APIキーが設定されていません。右上の設定アイコンからAPIキーを入力してください。');
            return;
        }
        if (!goal.trim()) {
            setError('目標を入力してください。');
            return;
        }
        setIsLoading(true);
        setError(null);
        setSuggestedTasks([]);

        const tasks = await generateStudyPlan(goal, apiKey);

        if (tasks) {
            setSuggestedTasks(tasks);
        } else {
            setError('計画の生成に失敗しました。もう一度お試しください。');
        }
        setIsLoading(false);
    };

    const handleAddTasks = (subjectId: string) => {
        if (!subjectId) return;

        const today = new Date();
        const newTasks = suggestedTasks.map((st, index) => {
            const taskDate = new Date(today);
            taskDate.setDate(today.getDate() + index); // Spread tasks over the next few days
            return {
                title: st.title,
                subjectId: subjectId,
                date: taskDate.toISOString().split('T')[0],
                type: TaskType.STUDY,
                duration: st.estimatedHours,
            };
        });

        onAddSuggestedTasks(newTasks);
        setSuggestedTasks([]);
        setGoal('');
    };

    return (
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-slate-200 mt-6 bg-gradient-to-br from-white to-indigo-50/30">
            <div className="flex items-center gap-3 mb-2">
                <div className="bg-gradient-to-br from-yellow-300 to-amber-500 p-2 rounded-lg text-white shadow-md">
                   <Icon name="sparkles" className="w-5 h-5" />
                </div>
                <h3 className="text-xl font-bold text-slate-800">AI 学習プランナー</h3>
            </div>
            <p className="text-sm text-slate-500 mb-6 ml-1">
                「2週間で物理をマスターしたい」などの目標を入力すると、AIが最適な学習スケジュールを提案します。
            </p>

            <div className="flex flex-col sm:flex-row gap-2">
                <input
                    type="text"
                    value={goal}
                    onChange={(e) => setGoal(e.target.value)}
                    placeholder="例: 中間テストで数学80点以上取るための計画"
                    className="flex-grow px-4 py-3 bg-white border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition shadow-sm"
                    disabled={isLoading}
                />
                <button
                    onClick={handleGeneratePlan}
                    className="px-6 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition flex items-center justify-center gap-2 disabled:bg-indigo-300 active:scale-95 whitespace-nowrap"
                    disabled={isLoading}
                >
                    {isLoading ? (
                        <>
                          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                          <span>生成中...</span>
                        </>
                    ) : (
                        '計画を提案'
                    )}
                </button>
            </div>
            {error && (
                <div className="mt-3 p-3 bg-rose-50 border border-rose-200 text-rose-600 rounded-lg text-sm flex items-start gap-2">
                     <Icon name="x" className="w-5 h-5 flex-shrink-0" />
                     {error}
                </div>
            )}

            {suggestedTasks.length > 0 && (
                <div className="mt-6 animate-fade-in border-t border-slate-200 pt-6">
                    <h4 className="font-bold text-slate-700 mb-3 flex items-center gap-2">
                        <Icon name="check" className="w-5 h-5 text-green-500" />
                        提案されたタスク ({suggestedTasks.length}件)
                    </h4>
                    <ul className="space-y-3 max-h-80 overflow-y-auto pr-2 custom-scrollbar">
                        {suggestedTasks.map((task, index) => (
                            <li key={index} className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex justify-between items-start gap-3 hover:shadow-md transition-shadow">
                                <div>
                                    <p className="font-bold text-slate-800">{task.title}</p>
                                    <p className="text-sm text-slate-500 mt-1 leading-relaxed">{task.description}</p>
                                </div>
                                <span className="flex-shrink-0 text-xs font-bold text-indigo-700 bg-indigo-100 px-2.5 py-1 rounded-full whitespace-nowrap">{task.estimatedHours}時間</span>
                            </li>
                        ))}
                    </ul>
                     <div className="mt-6 flex flex-col sm:flex-row gap-3 items-center">
                        <select
                            onChange={(e) => handleAddTasks(e.target.value)}
                            className="w-full sm:w-auto flex-grow px-4 py-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-green-500 focus:border-green-500 transition bg-white shadow-sm cursor-pointer"
                            defaultValue=""
                        >
                            <option value="" disabled>どの科目に追加しますか？</option>
                            {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                         <button onClick={() => setSuggestedTasks([])} className="w-full sm:w-auto px-6 py-3 bg-slate-100 text-slate-600 font-bold rounded-xl hover:bg-slate-200 transition">
                            キャンセル
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GeminiSuggester;

import React from 'react';
import { Subject, Task, TaskType } from '../types';
import Icon from './Icon';

interface CalendarProps {
  currentDate: Date;
  tasks: Task[];
  subjects: Subject[];
  onDateClick: (date: Date) => void;
  onTaskClick: (task: Task) => void;
  onPrevMonth: () => void;
  onNextMonth: () => void;
  onToggleTaskCompletion: (taskId: string) => void;
}

// Simplified holiday check for 2024-2025
const isJapaneseHoliday = (date: Date): boolean => {
  const year = date.getFullYear();
  const monthDay = `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;

  const holidays2024 = new Set([
    '01-01', '01-08', '02-11', '02-12', '02-23', '03-20', '04-29', 
    '05-03', '05-04', '05-05', '05-06', '07-15', '08-11', '08-12', 
    '09-16', '09-22', '09-23', '10-14', '11-03', '11-04', '11-23'
  ]);

  const holidays2025 = new Set([
    '01-01', '01-13', '02-11', '02-23', '02-24', '03-20', '04-29', 
    '05-03', '05-04', '05-05', '05-06', '07-21', '08-11', '09-15', 
    '09-23', '10-13', '11-03', '11-23', '11-24'
  ]);

  if (year === 2024) {
    return holidays2024.has(monthDay);
  }
  if (year === 2025) {
    return holidays2025.has(monthDay);
  }

  return false;
};


const Calendar: React.FC<CalendarProps> = ({ currentDate, tasks, subjects, onDateClick, onTaskClick, onPrevMonth, onNextMonth, onToggleTaskCompletion }) => {
  const month = currentDate.getMonth();
  const year = currentDate.getFullYear();

  const firstDayOfMonth = new Date(year, month, 1);
  const lastDayOfMonth = new Date(year, month + 1, 0);

  const startingDayIndex = firstDayOfMonth.getDay();
  const daysInMonthCount = lastDayOfMonth.getDate();
  const days = ['日', '月', '火', '水', '木', '金', '土'];

  const calendarCells = [];

  // 1. Add empty cells for days before the first day of the month
  for (let i = 0; i < startingDayIndex; i++) {
    calendarCells.push({ type: 'empty', key: `empty-start-${i}` });
  }

  // 2. Add cells for each day of the month
  for (let date = 1; date <= daysInMonthCount; date++) {
    const day = new Date(year, month, date);
    calendarCells.push({ type: 'day', day: day, key: day.toISOString().split('T')[0] });
  }

  // 3. Add empty cells to fill up the 6-week grid (total 42 cells)
  const totalCellsFilled = calendarCells.length;
  if (totalCellsFilled < 42) {
    const remainingCells = 42 - totalCellsFilled;
    for (let i = 0; i < remainingCells; i++) {
        calendarCells.push({ type: 'empty', key: `empty-end-${i}` });
    }
  }

  const getSubjectColor = (subjectId: string) => {
    return subjects.find(s => s.id === subjectId)?.color || 'gray';
  };

  return (
    <div className="bg-white p-4 sm:p-6 rounded-3xl shadow-lg border border-slate-200 flex flex-col h-full overflow-hidden">
      <div className="flex justify-between items-center mb-6 flex-shrink-0 px-2">
        <button onClick={onPrevMonth} className="p-2.5 rounded-full hover:bg-slate-100 transition-colors text-slate-500 hover:text-indigo-600">
          <Icon name="chevronLeft" className="w-5 h-5" />
        </button>
        <h2 className="text-xl sm:text-2xl font-bold text-slate-800 tracking-tight">
          {year}年 {month + 1}月
        </h2>
        <button onClick={onNextMonth} className="p-2.5 rounded-full hover:bg-slate-100 transition-colors text-slate-500 hover:text-indigo-600">
          <Icon name="chevronRight" className="w-5 h-5" />
        </button>
      </div>

      <div className="grid grid-cols-7 gap-2 text-center font-bold text-slate-400 text-xs sm:text-sm flex-shrink-0 mb-2">
        {days.map((day, index) => <div key={day} className={`py-1 ${index === 0 ? 'text-rose-400' : ''} ${index === 6 ? 'text-blue-400' : ''}`}>{day}</div>)}
      </div>

      {/* Modern Grid with Gaps and Rounded Cells */}
      <div className="grid grid-cols-7 grid-rows-6 gap-1 sm:gap-2 flex-grow bg-slate-50 p-2 rounded-2xl border border-slate-100">
        {calendarCells.map((cell) => {
          if (cell.type === 'day') {
            const day = cell.day;
            const dateStr = day.toISOString().split('T')[0];
            const tasksForDay = tasks.filter(task => task.date === dateStr);
            const isToday = new Date().toISOString().split('T')[0] === dateStr;

            const dayOfWeek = day.getDay();
            const isHoliday = isJapaneseHoliday(day);
            const isSunday = dayOfWeek === 0;
            const isSaturday = dayOfWeek === 6;

            const dateTextColor = isSunday || isHoliday ? 'text-rose-500' : isSaturday ? 'text-blue-500' : 'text-slate-600';

            return (
              <div
                key={dateStr}
                className={`bg-white rounded-xl p-1 sm:p-2 flex flex-col relative group cursor-pointer hover:shadow-md hover:-translate-y-0.5 transition-all duration-200 min-h-0 border border-transparent hover:border-indigo-100 ${isToday ? 'ring-2 ring-indigo-500 ring-offset-1 z-10' : 'shadow-sm'}`}
                onClick={() => onDateClick(day)}
              >
                <div className="flex justify-between items-start">
                    <span className={`text-xs sm:text-sm font-bold flex-shrink-0 w-6 h-6 flex items-center justify-center rounded-full transition-colors ${isToday ? 'bg-indigo-600 text-white' : dateTextColor}`}>
                      {day.getDate()}
                    </span>
                    {tasksForDay.length > 0 && (
                        <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 sm:hidden"></span>
                    )}
                </div>
                <div className="mt-1 space-y-1 overflow-y-auto flex-grow custom-scrollbar hidden sm:block">
                  {tasksForDay.slice(0, 3).map(task => { // Show max 3 tasks initially
                    const subjectColor = getSubjectColor(task.subjectId);
                    return (
                      <div
                        key={task.id}
                        onClick={(e) => { e.stopPropagation(); onTaskClick(task); }}
                        className={`px-1.5 py-0.5 rounded-md text-[10px] sm:text-xs transition-all flex items-center gap-1 cursor-pointer truncate border-l-2 ${task.isCompleted ? 'opacity-50 grayscale' : 'hover:opacity-80'}`}
                        style={{ backgroundColor: `${subjectColor}15`, borderLeftColor: subjectColor }}
                      >
                         {task.isCompleted && <Icon name="check" className="w-2.5 h-2.5 flex-shrink-0 text-green-600"/>}
                        <span className={`font-medium truncate ${task.isCompleted ? 'line-through text-slate-500' : 'text-slate-700'}`}>
                          {task.type === TaskType.DEADLINE && <span className="text-rose-500 font-bold mr-0.5">!</span>}
                          {task.title}
                        </span>
                      </div>
                    );
                  })}
                   {tasksForDay.length > 3 && (
                      <div className="text-[10px] text-center text-slate-400 font-medium leading-none py-0.5">+ {tasksForDay.length - 3}</div>
                  )}
                </div>
              </div>
            );
          }
          // Render empty cells
          return <div key={cell.key} className="rounded-xl"></div>;
        })}
      </div>
    </div>
  );
};

export default Calendar;

