import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Subject, Task, TaskType, UserProgress, Badge } from './types';
import useLocalStorage from './hooks/useLocalStorage';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import Header from './components/Header';
import SettingsMenu from './components/SettingsMenu';
import Sidebar from './components/Sidebar';
import ProgressView from './components/ProgressView';
import SubjectManager from './components/SubjectManager';
import HomeView from './components/HomeView';

const SIDEBAR_COLORS = [
  '#F87171', '#FB923C', '#FBBF24', '#A3E635', '#4ADE80', '#34D399', '#2DD4BF', '#60A5FA', '#818CF8', '#A78BFA', '#F472B6'
];

const INITIAL_BADGES: Badge[] = [
  { id: 'first_step', name: 'はじめの一歩', description: '最初のタスクを完了', icon: 'check', achieved: false, xpReward: 50 },
  { id: 'study_10h', name: '勉強家', description: '合計10時間勉強', icon: 'book', achieved: false, xpReward: 100 },
  { id: 'study_50h', name: '努力家', description: '合計50時間勉強', icon: 'book', achieved: false, xpReward: 500 },
  { id: 'perfect_week', name: 'パーフェクトウィーク', description: '1週間の全タスクを完了', icon: 'calendar', achieved: false, xpReward: 300 },
  { id: 'deadline_master', name: '締切マスター', description: '5つの提出タスクを完了', icon: 'flag', achieved: false, xpReward: 200 },
];

const XP_PER_HOUR = 20;
const XP_PER_DEADLINE = 50;
const LEVEL_UP_BASE_XP = 100;

export type View = 'home' | 'calendar' | 'progress' | 'subjects';

const App: React.FC = () => {
  const [subjects, setSubjects] = useLocalStorage<Subject[]>('subjects', []);
  const [tasks, setTasks] = useLocalStorage<Task[]>('tasks', []);
  const [userProgress, setUserProgress] = useLocalStorage<UserProgress>('userProgress', {
    level: 1,
    xp: 0,
    badges: INITIAL_BADGES,
  });
  const [apiKey, setApiKey] = useLocalStorage<string>('gemini_api_key', '');

  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [taskToEdit, setTaskToEdit] = useState<Task | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [notificationPermission, setNotificationPermission] = useState(Notification.permission);
  const [activeView, setActiveView] = useState<View>('home');

  const notificationTimeouts = useRef<number[]>([]);

  const handleRequestNotificationPermission = useCallback(() => {
    Notification.requestPermission().then(permission => {
        setNotificationPermission(permission);
    });
  }, []);

  useEffect(() => {
    notificationTimeouts.current.forEach(clearTimeout);
    notificationTimeouts.current = [];

    if (notificationPermission === 'granted') {
      const now = new Date();
      tasks.forEach(task => {
        if (task.notificationEnabled && task.startTime && !task.isCompleted) {
          const [hours, minutes] = task.startTime.split(':').map(Number);
          const notificationDate = new Date(task.date);
          notificationDate.setHours(hours, minutes, 0, 0);

          if (notificationDate > now) {
            const timeout = window.setTimeout(() => {
              new Notification('学習の時間です！', {
                body: `${task.title}`,
                icon: '/favicon.ico' 
              });
            }, notificationDate.getTime() - now.getTime());
            notificationTimeouts.current.push(timeout);
          }
        }
      });
    }

    return () => {
      notificationTimeouts.current.forEach(clearTimeout);
    };
  }, [tasks, notificationPermission]);

  const xpForNextLevel = LEVEL_UP_BASE_XP * userProgress.level;

  const checkAchievements = useCallback(() => {
    let newProgress = { ...userProgress };
    let newBadges = [...newProgress.badges];
    let changed = false;
    let totalXpGained = 0;

    const updateBadge = (id: string, condition: boolean) => {
        const badge = newBadges.find(b => b.id === id);
        if (badge && !badge.achieved && condition) {
            badge.achieved = true;
            totalXpGained += (badge.xpReward || 0);
            changed = true;
        }
    };

    updateBadge('first_step', tasks.some(t => t.isCompleted));

    const totalStudyHours = tasks
      .filter(t => t.type === TaskType.STUDY && t.isCompleted && t.duration)
      .reduce((sum, task) => sum + (task.duration || 0), 0);

    updateBadge('study_10h', totalStudyHours >= 10);
    updateBadge('study_50h', totalStudyHours >= 50);

    const completedDeadlines = tasks.filter(t => t.type === TaskType.DEADLINE && t.isCompleted).length;
    updateBadge('deadline_master', completedDeadlines >= 5);

    let currentXp = newProgress.xp + totalXpGained;
    let currentLevel = newProgress.level;
    let requiredXp = LEVEL_UP_BASE_XP * currentLevel;
    while (currentXp >= requiredXp) {
        currentXp -= requiredXp;
        currentLevel += 1;
        requiredXp = LEVEL_UP_BASE_XP * currentLevel;
        changed = true;
    }
    newProgress.level = currentLevel;
    newProgress.xp = currentXp;

    if (changed) {
      newProgress.badges = newBadges;
      setUserProgress(newProgress);
    }
  }, [tasks, userProgress, setUserProgress]);

  useEffect(() => {
    checkAchievements();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tasks]);

  const handleDateClick = (date: Date) => {
    setSelectedDate(date);
    setTaskToEdit(null);
    setIsModalOpen(true);
  };

  const handleTaskClick = (task: Task) => {
    setSelectedDate(new Date(task.date));
    setTaskToEdit(task);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskData: Omit<Task, 'id' | 'isCompleted'>) => {
    if(taskData.notificationEnabled && notificationPermission !== 'granted') {
        handleRequestNotificationPermission();
    }

    if (taskToEdit) {
      setTasks(tasks.map(t => t.id === taskToEdit.id ? { ...taskToEdit, ...taskData } : t));
    } else {
      const newTask: Task = {
        ...taskData,
        id: crypto.randomUUID(),
        isCompleted: false,
      };
      setTasks([...tasks, newTask]);
    }
    setTaskToEdit(null);
  };

  const handleToggleTaskCompletion = (taskId: string) => {
    let xpGained = 0;
    const updatedTasks = tasks.map(t => {
      if (t.id === taskId) {
        const wasCompleted = t.isCompleted;
        if (!wasCompleted) {
            if (t.type === TaskType.STUDY && t.duration) xpGained = t.duration * XP_PER_HOUR;
            else if (t.type === TaskType.DEADLINE) xpGained = XP_PER_DEADLINE;
        } else {
             if (t.type === TaskType.STUDY && t.duration) xpGained = -(t.duration * XP_PER_HOUR);
             else if (t.type === TaskType.DEADLINE) xpGained = -XP_PER_DEADLINE;
        }
        return { ...t, isCompleted: !t.isCompleted };
      }
      return t;
    });

    setUserProgress(prev => ({...prev, xp: Math.max(0, prev.xp + xpGained)}));
    setTasks(updatedTasks);
  };

  const handleAddSuggestedTasks = (newTasks: Omit<Task, 'id' | 'isCompleted'>[]) => {
      const tasksToAdd: Task[] = newTasks.map(t => ({
          ...t,
          id: crypto.randomUUID(),
          isCompleted: false
      }));
      setTasks(prevTasks => [...prevTasks, ...tasksToAdd]);
      setActiveView('calendar');
  };

  const renderContent = () => {
    switch(activeView) {
      case 'home':
        return (
          <HomeView 
            userProgress={userProgress}
            tasks={tasks}
            subjects={subjects}
            onNavigate={setActiveView}
            onTaskClick={handleTaskClick}
            onToggleTaskCompletion={handleToggleTaskCompletion}
          />
        );
      case 'calendar':
        return (
          <Calendar
            currentDate={currentDate} tasks={tasks} subjects={subjects}
            onDateClick={handleDateClick} onTaskClick={handleTaskClick}
            onPrevMonth={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))}
            onNextMonth={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))}
          />
        );
      case 'progress':
        return <ProgressView userProgress={userProgress} xpForNextLevel={xpForNextLevel} />;
      case 'subjects':
        return (
          <SubjectManager 
            subjects={subjects}
            setSubjects={setSubjects}
            tasks={tasks}
            setTasks={setTasks}
            SIDEBAR_COLORS={SIDEBAR_COLORS}
            onAddSuggestedTasks={handleAddSuggestedTasks}
            apiKey={apiKey}
          />
        );
      default:
        return null;
    }
  }

  return (
    <div className="flex flex-col h-screen bg-slate-100 relative overflow-hidden">
      <style>{`
        @keyframes modal-enter { from { opacity: 0; transform: translateY(20px) scale(0.98); } to { opacity: 1; transform: translateY(0) scale(1); } }
        .animate-modal-enter { animation: modal-enter 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards; }
        @keyframes settings-enter { from { opacity: 0; transform: translateY(-10px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
        .animate-settings-enter { animation: settings-enter 0.2s ease-out forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out forwards; }
        @keyframes overlay-enter { from { opacity: 0; } to { opacity: 1; } }
        .animate-overlay-enter { animation: overlay-enter 0.3s ease-out forwards; }
      `}</style>

      <Header 
        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        onNavigate={setActiveView}
      />

      <Sidebar
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        activeView={activeView}
        onNavigate={(view: View) => {
          setActiveView(view);
          setIsSidebarOpen(false);
        }}
      />

      {isSidebarOpen && (
          <div 
              className="fixed inset-0 bg-black bg-opacity-50 z-40 animate-overlay-enter md:hidden"
              onClick={() => setIsSidebarOpen(false)}
          ></div>
      )}

      <main className="flex-1 p-4 lg:p-6 overflow-hidden">
        <div className="h-full w-full overflow-y-auto">
          {renderContent()}
        </div>
      </main>

      <TaskModal
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveTask}
        subjects={subjects} selectedDate={selectedDate} taskToEdit={taskToEdit}
      />

      <SettingsMenu
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        notificationPermission={notificationPermission}
        onRequestNotificationPermission={handleRequestNotificationPermission}
        apiKey={apiKey}
        setApiKey={setApiKey}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserProgress, Task, TaskType, Subject } from '../types';
import Icon from './Icon';
import { View } from '../App';

interface HomeViewProps {
  userProgress: UserProgress;
  tasks: Task[];
  subjects: Subject[];
  onNavigate: (view: View) => void;
  onTaskClick: (task: Task) => void;
  onToggleTaskCompletion: (taskId: string) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ userProgress, tasks, subjects, onNavigate, onTaskClick, onToggleTaskCompletion }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const today = new Date().toISOString().split('T')[0];
  const todaysTasks = tasks.filter(t => t.date === today);
  const completedCount = todaysTasks.filter(t => t.isCompleted).length;

  // 最初は3件だけ表示し、展開時はすべて表示する
  const displayedTasks = isExpanded ? todaysTasks : todaysTasks.slice(0, 3);

  const upcomingDeadlines = tasks
    .filter(t => t.type === TaskType.DEADLINE && !t.isCompleted && t.date >= today)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(0, 3);

  const getSubject = (id: string) => subjects.find(s => s.id === id);

  return (
    <div className="space-y-6 animate-fade-in max-w-5xl mx-auto pb-10">
      {/* Welcome Card */}
      <section className="bg-gradient-to-r from-indigo-600 to-violet-600 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <h2 className="text-3xl font-bold mb-2">こんにちは！今日も頑張りましょう</h2>
          <p className="opacity-90 text-lg mb-6">
            {todaysTasks.length > 0 ? (
              <>
                今日は <span className="font-bold underline">{todaysTasks.length}件</span> の予定があります。
                {completedCount > 0 && ` (${completedCount}件 完了済み)`}
              </>
            ) : (
              "今日は予定がありません。"
            )}
          </p>
          <div className="flex gap-4">
             <button 
                onClick={() => onNavigate('calendar')}
                className="bg-white/20 hover:bg-white/30 backdrop-blur-md px-6 py-2.5 rounded-xl font-bold transition-all active:scale-95 flex items-center gap-2"
             >
                <Icon name="calendar" className="w-5 h-5" />
                カレンダーを見る
             </button>
             <button 
                onClick={() => onNavigate('subjects')}
                className="bg-white text-indigo-600 px-6 py-2.5 rounded-xl font-bold transition-all hover:bg-indigo-50 active:scale-95 shadow-lg"
             >
                新しい科目を追加
             </button>
          </div>
        </div>
        <div className="absolute top-[-20px] right-[-20px] w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>
        <div className="absolute bottom-[-50px] left-[10%] w-64 h-64 bg-indigo-400/20 rounded-full blur-3xl"></div>
      </section>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
        {/* Left Column: Today's Tasks */}
        <section className="bg-white rounded-3xl p-6 shadow-lg border border-slate-200 flex flex-col h-full min-h-[400px]">
           <div className="flex items-center justify-between mb-4 flex-shrink-0">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Icon name="check" className="w-6 h-6 text-green-500" />
                今日のタスク
              </h3>
              {todaysTasks.length > 3 && (
                <button 
                  onClick={() => setIsExpanded(!isExpanded)} 
                  className="text-sm text-indigo-600 hover:underline font-bold transition-all"
                >
                  {isExpanded ? '閉じる' : 'すべて表示'}
                </button>
              )}
           </div>

           <div className="flex-grow space-y-3 transition-all duration-300">
              {todaysTasks.length > 0 ? (
                displayedTasks.map(task => {
                  const sub = getSubject(task.subjectId);
                  return (
                    <div 
                        key={task.id} 
                        className={`group flex items-center gap-3 p-3 rounded-2xl border transition-all cursor-pointer animate-fade-in ${task.isCompleted ? 'bg-slate-50 border-slate-100 opacity-60' : 'bg-white border-slate-200 hover:border-indigo-300 hover:shadow-md'}`}
                        onClick={() => onTaskClick(task)}
                    >
                      <button 
                        onClick={(e) => { e.stopPropagation(); onToggleTaskCompletion(task.id); }}
                        className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${task.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-slate-300 group-hover:border-indigo-400'}`}
                      >
                        {task.isCompleted && <Icon name="check" className="w-4 h-4" />}
                      </button>
                      <div className="flex-grow min-w-0">
                        <p className={`font-bold truncate ${task.isCompleted ? 'line-through text-slate-400' : 'text-slate-700'}`}>{task.title}</p>
                        <div className="flex items-center gap-2 mt-0.5">
                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: sub?.color || '#ccc' }}></span>
                            <span className="text-xs text-slate-500">{sub?.name}</span>
                        </div>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="h-full flex flex-col items-center justify-center py-10 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                    <p className="text-slate-400 font-medium text-center px-4">今日はタスクがありません<br/><span className="text-xs">ゆっくり休むか、新しい予定を追加しましょう</span></p>
                </div>
              )}
           </div>

           {!isExpanded && todaysTasks.length > 3 && (
              <p className="text-center text-xs text-slate-400 font-medium pt-4 flex-shrink-0">
                ほか {todaysTasks.length - 3} 件の予定があります
              </p>
           )}
        </section>

        {/* Right Column: Status & Deadlines */}
        <div className="flex flex-col gap-6">
          {/* Level Progress */}
          <section className="bg-white rounded-3xl p-6 shadow-lg border border-slate-200 flex-1 flex flex-col justify-center">
            <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
              <Icon name="sparkles" className="w-6 h-6 text-amber-500" />
              ステータス
            </h3>
            <div className="flex items-center justify-between mb-3">
              <span className="text-3xl font-black text-indigo-600">Lv.{userProgress.level}</span>
              <span className="text-sm font-bold text-slate-400 bg-slate-50 px-3 py-1 rounded-full border border-slate-100">XP {Math.round(userProgress.xp)} / {userProgress.level * 100}</span>
            </div>
            <div className="w-full bg-slate-100 rounded-full h-4 overflow-hidden shadow-inner">
               <div 
                  className="bg-gradient-to-r from-indigo-500 to-violet-500 h-full rounded-full transition-all duration-1000 ease-out shadow-lg"
                  style={{ width: `${(userProgress.xp / (userProgress.level * 100)) * 100}%` }}
               ></div>
            </div>
          </section>

          {/* Deadlines */}
          <section className="bg-white rounded-3xl p-6 shadow-lg border border-slate-200 flex-1 flex flex-col h-full">
            <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
              <Icon name="flag" className="w-6 h-6 text-rose-500" />
              直近の締め切り
            </h3>
            <div className="flex-grow space-y-3">
               {upcomingDeadlines.length > 0 ? (
                 upcomingDeadlines.map(task => {
                   const daysLeft = Math.ceil((new Date(task.date).getTime() - new Date(today).getTime()) / (1000 * 60 * 60 * 24));
                   return (
                     <div 
                        key={task.id}
                        className="flex items-center justify-between p-3.5 bg-rose-50/50 border border-rose-100 rounded-2xl cursor-pointer hover:shadow-md hover:border-rose-200 transition-all active:scale-[0.98]"
                        onClick={() => onTaskClick(task)}
                     >
                        <div className="min-w-0">
                           <p className="font-bold text-slate-700 truncate">{task.title}</p>
                           <p className="text-xs text-rose-600 font-bold flex items-center gap-1">
                             <span className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse"></span>
                             あと {daysLeft === 0 ? '今日中' : `${daysLeft}日`}
                           </p>
                        </div>
                        <div className="text-right flex-shrink-0">
                            <span className="text-[10px] text-slate-400 bg-white px-2 py-1 rounded-lg border border-rose-100 font-black">{task.date.replace(/^\d{4}-/, '')}</span>
                        </div>
                     </div>
                   );
                 })
               ) : (
                 <div className="h-full flex items-center justify-center py-6">
                    <p className="text-center text-slate-400 text-sm font-medium">期限の迫った課題はありません</p>
                 </div>
               )}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default HomeView;

import { GoogleGenAI, Type } from "@google/genai";
import { SuggestedTask } from '../types';

export const generateStudyPlan = async (goal: string, apiKey: string): Promise<SuggestedTask[] | null> => {
  if (!apiKey) {
    console.error("API key is missing.");
    return null;
  }

  const ai = new GoogleGenAI({ apiKey: apiKey });

  try {
    const prompt = `あなたは優秀な学習プランナーです。生徒の目標「${goal}」を達成するための、構造化された学習タスクのJSON配列を作成してください。各タスクには、タイトル(title)、内容(description)、推定学習時間(estimatedHours)（時間単位の数値）を含めてください。現実的で実行可能な計画を提案してください。`;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: {
                type: Type.STRING,
                description: 'タスクのタイトル',
              },
              description: {
                type: Type.STRING,
                description: 'タスクの具体的な内容',
              },
              estimatedHours: {
                type: Type.NUMBER,
                description: '推定学習時間（時間単位）',
              },
            },
            required: ["title", "description", "estimatedHours"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) {
        console.error("Gemini response is empty");
        return null;
    }

    const jsonString = text.trim();
    const tasks = JSON.parse(jsonString) as SuggestedTask[];
    return tasks;

  } catch (error) {
    console.error("Error generating study plan with Gemini:", error);
    return null;
  }
};

import React, { useState } from 'react';
import { Subject, Task, TaskType } from '../types';
import Icon from './Icon';

interface CalendarProps {
  currentDate: Date;
  tasks: Task[];
  subjects: Subject[];
  onDateClick: (date: Date) => void;
  onTaskClick: (task: Task) => void;
  onPrevMonth: () => void;
  onNextMonth: () => void;
}

// Simplified holiday check for 2024-2025
const isJapaneseHoliday = (date: Date): boolean => {
  const year = date.getFullYear();
  const monthDay = `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;

  const holidays2024 = new Set([
    '01-01', '01-08', '02-11', '02-12', '02-23', '03-20', '04-29', 
    '05-03', '05-04', '05-05', '05-06', '07-15', '08-11', '08-12', 
    '09-16', '09-22', '09-23', '10-14', '11-03', '11-04', '11-23'
  ]);

  const holidays2025 = new Set([
    '01-01', '01-13', '02-11', '02-23', '02-24', '03-20', '04-29', 
    '05-03', '05-04', '05-05', '05-06', '07-21', '08-11', '09-15', 
    '09-23', '10-13', '11-03', '11-23', '11-24'
  ]);

  if (year === 2024) {
    return holidays2024.has(monthDay);
  }
  if (year === 2025) {
    return holidays2025.has(monthDay);
  }

  return false;
};

interface CalendarCell {
    type: 'current' | 'prev' | 'next';
    day: Date;
    key: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentDate, tasks, subjects, onDateClick, onTaskClick, onPrevMonth, onNextMonth }) => {
  const [hoveredDate, setHoveredDate] = useState<string | null>(null);

  const month = currentDate.getMonth();
  const year = currentDate.getFullYear();

  const monthStart = new Date(year, month, 1);
  const monthEnd = new Date(year, month + 1, 0);
  const startDateDay = monthStart.getDay(); // 0 (Sun) - 6 (Sat)
  const endDateCount = monthEnd.getDate();

  // 前月の日付計算用
  const prevMonthEnd = new Date(year, month, 0);
  const prevMonthEndDateCount = prevMonthEnd.getDate();

  const calendarCells: CalendarCell[] = [];

  // 前月分
  for (let i = 0; i < startDateDay; i++) {
      const day = new Date(year, month - 1, prevMonthEndDateCount - startDateDay + 1 + i);
      calendarCells.push({ type: 'prev', day, key: `prev-${day.toISOString()}` });
  }

  // 当月分
  for (let i = 1; i <= endDateCount; i++) {
      const day = new Date(year, month, i);
      calendarCells.push({ type: 'current', day, key: `curr-${day.toISOString()}` });
  }

  // 翌月分（42個になるまで埋める）
  const remaining = 42 - calendarCells.length;
  for (let i = 1; i <= remaining; i++) {
      const day = new Date(year, month + 1, i);
      calendarCells.push({ type: 'next', day, key: `next-${day.toISOString()}` });
  }

  const getSubject = (id: string) => subjects.find(s => s.id === id);

  return (
    <div className="bg-white p-4 sm:p-6 pb-8 rounded-3xl shadow-xl border border-slate-200 flex flex-col">
      <style>{`
        @keyframes popover-enter {
            from { opacity: 0; transform: scale(0.95) translateY(5px); }
            to { opacity: 1; transform: scale(1) translateY(0); }
        }
        .animate-popover { animation: popover-enter 0.2s ease-out forwards; }
      `}</style>

      <div className="flex justify-between items-center mb-6 flex-shrink-0 px-2">
        <button onClick={onPrevMonth} className="p-2.5 rounded-full hover:bg-slate-100 transition-colors text-slate-500 hover:text-indigo-600 active:scale-90">
          <Icon name="chevronLeft" className="w-5 h-5" />
        </button>
        <h2 className="text-xl sm:text-2xl font-black text-slate-800 tracking-tight">
          {year}年 {month + 1}月
        </h2>
        <button onClick={onNextMonth} className="p-2.5 rounded-full hover:bg-slate-100 transition-colors text-slate-500 hover:text-indigo-600 active:scale-90">
          <Icon name="chevronRight" className="w-5 h-5" />
        </button>
      </div>

      <div className="grid grid-cols-7 gap-2 text-center font-black text-slate-400 text-[10px] sm:text-xs flex-shrink-0 mb-3 px-1">
        {['日', '月', '火', '水', '木', '金', '土'].map((day, index) => <div key={day} className={`py-1 ${index === 0 ? 'text-rose-400' : ''} ${index === 6 ? 'text-blue-400' : ''}`}>{day}</div>)}
      </div>

      {/* Grid Container */}
      <div className="grid grid-cols-7 gap-1 sm:gap-2 bg-slate-50 p-2 sm:p-3 rounded-[2rem] border border-slate-100 min-h-[500px]">
        {calendarCells.map((cell) => {
            const day = cell.day;
            if (!day) return null; // Guard against undefined day

            const dateStr = day.toISOString().split('T')[0];
            const tasksForDay = tasks.filter(task => task.date === dateStr);
            const isToday = new Date().toISOString().split('T')[0] === dateStr;

            const dayOfWeek = day.getDay();
            const isHoliday = isJapaneseHoliday(day);
            const isSunday = dayOfWeek === 0;
            const isSaturday = dayOfWeek === 6;

            // 文字色の決定
            let dateTextColor = 'text-slate-600';
            if (cell.type !== 'current') {
                dateTextColor = 'text-slate-300'; // 前月・翌月は薄く
            } else if (isSunday || isHoliday) {
                dateTextColor = 'text-rose-500';
            } else if (isSaturday) {
                dateTextColor = 'text-blue-500';
            }

            // 背景色とボーダーの決定
            let containerClass = "bg-white border-slate-100 hover:border-indigo-300 shadow-sm";
            if (cell.type !== 'current') {
                containerClass = "bg-slate-50/50 border-transparent shadow-none"; // 前月・翌月は背景を薄く、ボーダーなし
            } else if (isToday) {
                 containerClass = "bg-white ring-[3px] ring-indigo-500 ring-offset-2 z-10 shadow-md";
            }

            // ホバー時の背景色
            const hoverClass = (cell.type === 'current' && hoveredDate === dateStr) ? 'bg-indigo-50/30' : '';

            return (
              <div
                key={cell.key}
                className={`rounded-2xl p-1 sm:p-2 flex flex-col relative group cursor-pointer transition-all duration-200 min-h-0 border ${containerClass} ${hoverClass}`}
                onClick={() => {
                    // 前月・翌月の日付をクリックした場合の挙動
                    if (cell.type === 'prev') onPrevMonth();
                    else if (cell.type === 'next') onNextMonth();
                    else onDateClick(day);
                }}
                onMouseEnter={() => cell.type === 'current' && setHoveredDate(dateStr)}
                onMouseLeave={() => setHoveredDate(null)}
              >
                <div className="flex justify-between items-start">
                    <span className={`text-xs sm:text-sm font-black flex-shrink-0 w-6 h-6 sm:w-7 sm:h-7 flex items-center justify-center rounded-full transition-colors ${isToday ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200' : dateTextColor}`}>
                      {day.getDate()}
                    </span>
                    {tasksForDay.length > 0 && cell.type === 'current' && (
                        <div className="flex gap-0.5 sm:hidden mt-1 mr-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-indigo-400"></span>
                        </div>
                    )}
                </div>

                <div className={`mt-1.5 space-y-1 overflow-y-auto flex-grow hidden sm:block ${cell.type !== 'current' ? 'opacity-30' : ''}`}>
                  {tasksForDay.slice(0, 3).map(task => {
                    const sub = getSubject(task.subjectId);
                    return (
                      <div
                        key={task.id}
                        onClick={(e) => {
                            e.stopPropagation();
                            onTaskClick(task);
                        }}
                        className={`px-1.5 py-1 rounded-lg text-[9px] lg:text-[10px] truncate border-l-[3px] shadow-sm mb-1 ${task.isCompleted ? 'opacity-40 grayscale' : 'bg-white'}`}
                        style={{ borderLeftColor: sub?.color || '#ccc' }}
                      >
                        <span className={`truncate block ${task.isCompleted ? 'line-through' : 'text-slate-700 font-bold'}`}>
                          {task.title}
                        </span>
                      </div>
                    );
                  })}
                  {tasksForDay.length > 3 && (
                      <div className="text-[9px] text-center text-slate-400 font-black pt-0.5">+ {tasksForDay.length - 3}</div>
                  )}
                </div>

                {/* Hover Popover (当月のみ) */}
                {hoveredDate === dateStr && cell.type === 'current' && tasksForDay.length > 0 && (
                    <div className="absolute top-0 left-full ml-3 z-[60] w-64 bg-white/95 backdrop-blur-md rounded-[1.5rem] shadow-2xl border border-slate-200 p-4 animate-popover pointer-events-none md:pointer-events-auto">
                        <div className="flex items-center justify-between mb-4 border-b border-slate-100 pb-2">
                            <h4 className="font-black text-slate-800 flex items-center gap-2">
                                <Icon name="calendar" className="w-4 h-4 text-indigo-500" />
                                {day.getMonth() + 1}月{day.getDate()}日
                            </h4>
                        </div>
                        <div className="space-y-2.5 max-h-60 overflow-y-auto pr-1">
                            {tasksForDay.map(task => {
                                const sub = getSubject(task.subjectId);
                                return (
                                    <div 
                                      key={task.id} 
                                      className="p-2.5 rounded-xl bg-slate-50 border border-slate-100 hover:bg-white transition-colors cursor-pointer"
                                      onClick={(e) => {
                                        e.stopPropagation();
                                        onTaskClick(task);
                                      }}
                                    >
                                        <div className="flex items-start gap-2.5">
                                            <div className="w-2.5 h-2.5 rounded-full mt-1 flex-shrink-0 shadow-sm" style={{ backgroundColor: sub?.color || '#ccc' }}></div>
                                            <div className="min-w-0 flex-1">
                                                <p className={`text-sm font-bold leading-tight ${task.isCompleted ? 'line-through text-slate-400' : 'text-slate-700'}`}>{task.title}</p>
                                                <div className="flex items-center gap-2 mt-1.5">
                                                    <span className={`text-[9px] px-1.5 py-0.5 rounded-md font-black uppercase ${task.type === TaskType.STUDY ? 'bg-indigo-100 text-indigo-600' : 'bg-rose-100 text-rose-600'}`}>
                                                      {task.type === TaskType.STUDY ? '学習' : '提出'}
                                                    </span>
                                                    {task.duration && <span className="text-[9px] text-slate-400 font-bold">{task.duration}h</span>}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                        <p className="mt-4 text-[9px] text-center text-slate-400 font-black tracking-widest uppercase">Click to Edit</p>
                    </div>
                )}
              </div>
            );
        })}
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState } from 'react';
import { UserProgress, Task, TaskType, Subject } from '../types';
import Icon from './Icon';
import { View } from '../App';

interface HomeViewProps {
  userProgress: UserProgress;
  tasks: Task[];
  subjects: Subject[];
  onNavigate: (view: View) => void;
  onTaskClick: (task: Task) => void;
  onToggleTaskCompletion: (taskId: string) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ userProgress, tasks, subjects, onNavigate, onTaskClick, onToggleTaskCompletion }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const today = new Date().toISOString().split('T')[0];
  const todaysTasks = tasks.filter(t => t.date === today);
  const completedCount = todaysTasks.filter(t => t.isCompleted).length;

  // 最初は3件だけ表示し、展開時はすべて表示する
  const displayedTasks = isExpanded ? todaysTasks : todaysTasks.slice(0, 3);

  const upcomingDeadlines = tasks
    .filter(t => t.type === TaskType.DEADLINE && !t.isCompleted && t.date >= today)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(0, 3);

  const getSubject = (id: string) => subjects.find(s => s.id === id);

  return (
    <div className="space-y-6 animate-fade-in max-w-5xl mx-auto pb-10">
      {/* Welcome Card */}
      <section className="bg-gradient-to-r from-indigo-600 to-violet-600 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <h2 className="text-3xl font-bold mb-2">こんにちは！今日も頑張りましょう</h2>
          <p className="opacity-90 text-lg mb-6">
            {todaysTasks.length > 0 ? (
              <>
                今日は <span className="font-bold underline">{todaysTasks.length}件</span> の予定があります。
                {completedCount > 0 && ` (${completedCount}件 完了済み)`}
              </>
            ) : (
              "今日は予定がありません。"
            )}
          </p>
          <div className="flex gap-4">
             <button 
                onClick={() => onNavigate('calendar')}
                className="bg-white/20 hover:bg-white/30 backdrop-blur-md px-6 py-2.5 rounded-xl font-bold transition-all active:scale-95 flex items-center gap-2"
             >
                <Icon name="calendar" className="w-5 h-5" />
                カレンダーを見る
             </button>
             <button 
                onClick={() => onNavigate('subjects')}
                className="bg-white text-indigo-600 px-6 py-2.5 rounded-xl font-bold transition-all hover:bg-indigo-50 active:scale-95 shadow-lg"
             >
                新しい科目を追加
             </button>
          </div>
        </div>
        <div className="absolute top-[-20px] right-[-20px] w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>
        <div className="absolute bottom-[-50px] left-[10%] w-64 h-64 bg-indigo-400/20 rounded-full blur-3xl"></div>
      </section>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
        {/* Left Column: Today's Tasks */}
        <section className="bg-white rounded-3xl p-6 shadow-lg border border-slate-200 flex flex-col h-full min-h-[400px]">
           <div className="flex items-center justify-between mb-4 flex-shrink-0">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Icon name="check" className="w-6 h-6 text-green-500" />
                今日のタスク
              </h3>
              {todaysTasks.length > 3 && (
                <button 
                  onClick={() => setIsExpanded(!isExpanded)} 
                  className="text-sm text-indigo-600 hover:underline font-bold transition-all"
                >
                  {isExpanded ? '閉じる' : 'すべて表示'}
                </button>
              )}
           </div>

           <div className="flex-grow space-y-3 transition-all duration-300">
              {todaysTasks.length > 0 ? (
                displayedTasks.map(task => {
                  const sub = getSubject(task.subjectId);
                  return (
                    <div 
                        key={task.id} 
                        className={`group flex items-center gap-3 p-3 rounded-2xl border transition-all cursor-pointer animate-fade-in ${task.isCompleted ? 'bg-slate-50 border-slate-100 opacity-60' : 'bg-white border-slate-200 hover:border-indigo-300 hover:shadow-md'}`}
                        onClick={() => onTaskClick(task)}
                    >
                      <button 
                        onClick={(e) => { e.stopPropagation(); onToggleTaskCompletion(task.id); }}
